# Test flood fill from edges theory
def flood_fill_from_edges(grid, fill_color=3):
    """Fill all cells connected to the grid boundary with fill_color"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    queue = []
    visited = [[False]*w for _ in range(h)]

    # Add all edge 9s to queue
    for r in range(h):
        if grid[r][0] == 9:
            queue.append((r, 0))
            visited[r][0] = True
        if grid[r][w-1] == 9:
            queue.append((r, w-1))
            visited[r][w-1] = True
    for c in range(w):
        if grid[0][c] == 9:
            queue.append((0, c))
            visited[0][c] = True
        if grid[h-1][c] == 9:
            queue.append((h-1, c))
            visited[h-1][c] = True

    # BFS
    from collections import deque
    for r, c in queue:
        if grid[r][c] == 9:
            result[r][c] = fill_color
            queue.remove((r,c))
            queue.append((r,c))
    queue = deque(queue)

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                if not visited[nr][nc] and grid[nr][nc] == 9:
                    visited[nr][nc] = True
                    result[nr][nc] = fill_color
                    queue.append((nr, nc))

    return result

