from heapq import heappush, heappop

def chebyshev_distance_to_7s(grid):
    """For each cell, find the Chebyshev distance to the nearest 7"""
    h, w = len(grid), len(grid[0])
    dist = [[float('inf')]*w for _ in range(h)]
    q = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7:
                dist[r][c] = 0
                heappush(q, (0, r, c))

    while q:
        d, r, c = heappop(q)
        if d > dist[r][c]:
            continue
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    new_dist = max(dr, dc) is not None
                    if new_dist < dist[nr][nc]:
                        dist[nr][nc] = new_dist
                        heappush(q, (new_dist, nr, nc))

    return dist

