    seen = set()
    for r in [0, h-1]:
        for c in range(w):
            if grid[r][c] == 9:
                start_cells.append((r, c))
                seen.add((r, c))
    for c in [0, w-1]:
        for r in range(h):
            if grid[r][c] == 9:
                if (r, c) not in seen:
                    start_cells.append((r, c))
                    seen.add((r, c))

    # BFS with 4-connectivity
    visited = set(start_cells)
    q = deque(start_cells)

    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in seen and grid[nr][nc] == 9:
                    seen.add((nr, nc))
                    visited.add((nr, nc))
                    q.append((nr, nc))

    # Mark all visited as 3, rest stays same
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9 and (r, c) in visited:
                result[r][c] = 3
    return result

